-- Forward recovery: native scene closure required, gates off, code/catalog/history retained.
BEGIN;
SET LOCAL search_path='';
DO $joint_pre$
DECLARE rr mission_factory_owner.editor_release_readiness%ROWTYPE;p jsonb;f jsonb;
